func (r *Root) IsKeyedService(t reflect.Type, key any) bool {
	if key == nil {
		return r.IsService(t)
	}
	if key == godi.AnyKey {
		return false
	}
	switch t {
	case reflect.TypeFor[auth.Handler]():
		switch key {
		case gois.DefaultCookieAuthenticationScheme:
			return true
		case gois.ExternalCookieAuthenticationScheme:
			return true
		}
	}
	return false
}

func (r *Root) GetKeyedService(t reflect.Type, key any) any {
	if r.closed {
		panic(godi.ProviderClosedError())
	}
	if key == nil {
		return r.GetService(t)
	}
	if key == godi.AnyKey {
		panic(godi.AnyKeySingleResolveError(t))
	}
	switch t {
	case reflect.TypeFor[auth.Handler]():
		switch key {
		case gois.DefaultCookieAuthenticationScheme:
			return r.NewHandler_gois_DefaultCookieAuthenticationScheme()
		case gois.ExternalCookieAuthenticationScheme:
			return r.NewHandler_gois_ExternalCookieAuthenticationScheme()
		}
	}
	return nil
}

