func (r *Root) CreateScope() godi.Scope {
	if r.closed {
		panic(godi.ProviderClosedError())
	}
	s := &scope{root: r}
	s.f_DefaultHttpContextAccessor = accessor.NewDefaultHttpContextAccessor()
	s.f_HandlerProvider = (func(p godi.Provider) auth.HandlerProvider {
		return core.NewHandlerProvider(godi.GetRequired[auth.SchemeProvider](p), p)
	})(s)
	s.f_UserSession = (func(p godi.Provider) services.UserSession {
		return impl.NewUserSession(
			godi.GetRequired[accessor.HttpContextAccessor](p),
			godi.GetRequired[auth.HandlerProvider](p),
			godi.GetRequired[*options.WicketOptions](p),
			godi.GetRequired[services.SystemClock](p),
			impl.NewServerUrlsFromAccessor(godi.GetRequired[accessor.HttpContextAccessor](p)),
			godi.GetRequired[*slog.Logger](p),
			godi.GetRequired[auth.SchemeProvider](p),
			godi.GetRequired[session.Store](p),
		)
	})(s)
	s.f_Service = core.NewService(s.NewAuthSchemeProvider(), s.f_HandlerProvider)
	return s
}

func (r *Root) Close() error {
	r.closed = true
	return nil
}

